package com.myproject.video.video_platform.controller.commerce;
import com.fasterxml.jackson.databind.*;
import com.myproject.video.video_platform.common.enums.products.*;
import com.myproject.video.video_platform.common.enums.products.course.LessonType;
import com.myproject.video.video_platform.entity.products.*;
import com.myproject.video.video_platform.entity.products.course.*;
import com.myproject.video.video_platform.entity.products.download.*;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.repository.admin.AdminAuditLogRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.junit.jupiter.api.*;
import java.util.*;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
class CatalogProductOwnershipPublicationTest extends CatalogContentBoundaryTest {
 @Autowired AdminAuditLogRepository audits;
 @AfterEach void cleanAudit(){audits.deleteAll();}
 String role(User u){return u==owner?"Creator owner":u.getRoles().iterator().next().getRoleName();}
 Map<String,Object> payload(ProductType t,User u){Map<String,Object>b=new LinkedHashMap<>();b.put("type",t.name());b.put("name","QA isolated "+t);b.put("description","QA original description");if(u!=null)b.put("userId",u.getUserId().toString());return b;}
 JsonNode create(String c,String label,User caller,Map<String,Object>b,int expected)throws Exception{return perform(c,label,mutation(post("/api/products"),caller).content(mapper.writeValueAsString(b)),expected);}
 Product entity(JsonNode n){return products.findById(UUID.fromString(n.path("id").asText())).orElseThrow();}
 JsonNode read(String c,String label,Product p,User u)throws Exception{return productRead(c,label,p,u,false);}
 JsonNode patchBody(String c,String label,Product p,User u,Map<String,Object>b,int expected)throws Exception{return perform(c,label,mutation(patch("/api/products/"+p.getId()),u).content(mapper.writeValueAsString(b)),expected);}
 void defaults(ProductType t,User expected,JsonNode n){assertEquals(t.name(),n.path("type").asText());assertEquals(expected.getUserId().toString(),n.path("userId").asText());assertEquals("DRAFT",n.path("status").asText());assertEquals("free",n.path("price").asText());assertEquals("EUR",n.path("currency").asText());assertEquals(t==ProductType.MEMBERSHIP?"RECURRING":"ONE_TIME",n.path("pricingModel").asText());if(t==ProductType.MEMBERSHIP)assertEquals("MONTH",n.path("billingInterval").asText());else assertTrue(n.path("billingInterval").isNull());assertFalse(n.path("createdAt").isNull());Product p=entity(n);assertEquals(expected.getUserId(),p.getUser().getUserId());assertEquals(t,p.getType());assertEquals(ProductStatus.DRAFT,p.getStatus());assertEquals(0,p.getPrice().compareTo(BigDecimal.ZERO));}
 @Test void papi001CreatorOwnsAllTypesDespiteForeignOwner()throws Exception{User other=extra("other-creator",owner);for(ProductType t:ProductType.values()){JsonNode n=create("PAPI-001",t+"-foreign-owner",owner,payload(t,other),201);defaults(t,owner,n);assertEquals(n,read("PAPI-001",t+"-saved-read",entity(n),owner));}assertEquals(4,products.count());assertEquals(0,audits.count());}
 @Test void papi002AdminCreatesAllTypesForSelectedCreatorAndAudits()throws Exception{User other=extra("selected-creator",owner);Set<String>created=new HashSet<>();for(ProductType t:ProductType.values()){JsonNode n=create("PAPI-002",t+"-admin-create",admin,payload(t,other),201);defaults(t,other,n);created.add(n.path("id").asText());assertEquals(n,read("PAPI-002",t+"-owner-read",entity(n),other));}JsonNode list=perform("PAPI-002","selected-owner-management-list",get("/api/products").param("userId",other.getUserId().toString()).cookie(auth(other)),200);Set<String>got=new HashSet<>();for(JsonNode n:list)got.add(n.path("id").asText());assertEquals(created,got);assertEquals(4,audits.count());for(var a:audits.findAll()){assertEquals(admin.getUserId(),a.getActorUserId());assertEquals("PRODUCT_CREATE",a.getAction());assertEquals("PRODUCT",a.getTargetType());assertTrue(created.contains(a.getTargetId()));assertNull(a.getBeforeSummary());assertTrue(a.getAfterSummary().contains("ownerId="+other.getUserId()));assertNotNull(a.getCreatedAt());}}
 @Test void papi003AdminInvalidOwnersNoProductsOrAudits()throws Exception{for(ProductType t:ProductType.values())for(String variant:List.of("missing","null","blank","unknown","user","admin","invalid-uuid")){Map<String,Object>b=payload(t,null);switch(variant){case"null"->b.put("userId",null);case"blank"->b.put("userId","  ");case"unknown"->b.put("userId",UUID.randomUUID().toString());case"user"->b.put("userId",buyer.getUserId().toString());case"admin"->b.put("userId",admin.getUserId().toString());case"invalid-uuid"->b.put("userId","not-a-uuid");}create("PAPI-003",t+"-"+variant,admin,b,variant.equals("unknown")?404:variant.equals("invalid-uuid")?400:403);assertEquals(0,products.count());assertEquals(0,audits.count());}}
 @Test void papi004UserDeniedAllMutationRoutesAllTypes()throws Exception{for(ProductType t:ProductType.values()){Product p=seed(t,owner,"10",ProductStatus.DRAFT);JsonNode before=read("PAPI-004",t+"-before",p,owner);Map<String,Object>b=payload(t,owner);b.put("id",p.getId().toString());b.put("name","QA rejected User mutation");String body=mapper.writeValueAsString(b);perform("PAPI-004",t+"-post",mutation(post("/api/products"),buyer).content(body),403);perform("PAPI-004",t+"-put",mutation(put("/api/products"),buyer).content(body),403);patchBody("PAPI-004",t+"-patch",p,buyer,b,403);perform("PAPI-004",t+"-canonical-delete",mutation(delete("/api/products/"+p.getId()),buyer),403);perform("PAPI-004",t+"-legacy-delete",mutation(delete("/api/products"),buyer).param("userId",owner.getUserId().toString()).param("productType",t.name()).param("id",p.getId().toString()),403);assertEquals(before,read("PAPI-004",t+"-unchanged",p,owner));}assertEquals(4,products.count());assertEquals(0,audits.count());}
 @Test void papi005NonownerCreatorDeniedWithForgedOwnerAllTypes()throws Exception{User other=extra("nonowner-creator",owner);for(ProductType t:ProductType.values()){Product p=seed(t,owner,"10",ProductStatus.DRAFT);if(t==ProductType.COURSE)courseContent(p);if(t==ProductType.DOWNLOAD)downloadFile(p);JsonNode before=read("PAPI-005",t+"-before",p,owner);for(User supplied:List.of(owner,other)){Map<String,Object>b=payload(t,supplied);b.put("id",p.getId().toString());b.put("name","QA rejected nonowner edit");patchBody("PAPI-005",t+"-patch-owner-"+role(supplied),p,other,b,403);perform("PAPI-005",t+"-put-owner-"+role(supplied),mutation(put("/api/products"),other).content(mapper.writeValueAsString(b)),403);perform("PAPI-005",t+"-delete-owner-"+role(supplied),mutation(delete("/api/products/"+p.getId()),other).param("userId",supplied.getUserId().toString()),403);assertEquals(before,read("PAPI-005",t+"-unchanged",p,owner));}}assertEquals(4,products.count());assertEquals(0,audits.count());assertEquals(1,files.count());}
 @Test void papi007PatchPathIdentityNestedAndOmittedPreservation()throws Exception{User other=extra("patch-other-creator",owner);Product foreign=seed(ProductType.CONSULTATION,other,"30",ProductStatus.DRAFT);JsonNode untouched=read("PAPI-007","foreign-before",foreign,other);for(User caller:List.of(owner,admin))for(ProductType t:List.of(ProductType.COURSE,ProductType.DOWNLOAD)){Product p=seed(t,owner,"10",ProductStatus.DRAFT);if(t==ProductType.COURSE)courseContent(p);else downloadFile(p);JsonNode before=read("PAPI-007",role(caller)+t+"-before",p,owner);Map<String,Object>b=new LinkedHashMap<>();b.put("id",foreign.getId().toString());b.put("type","MEMBERSHIP");b.put("userId",other.getUserId().toString());b.put("name","QA legitimate shared edit");b.put("details",Map.of("sections",List.of(Map.of("title","QA forged replacement","position",99,"lessons",List.of()))));JsonNode n=patchBody("PAPI-007",role(caller)+t+"-patch",p,caller,b,200);assertEquals(p.getId().toString(),n.path("id").asText());assertEquals(t.name(),n.path("type").asText());assertEquals(owner.getUserId().toString(),n.path("userId").asText());assertEquals("QA legitimate shared edit",n.path("name").asText());assertEquals(before.path("details"),n.path("details"));assertEquals(before.path("description"),n.path("description"));assertEquals(before.path("price"),n.path("price"));assertEquals(before.path("status"),n.path("status"));assertEquals(n,read("PAPI-007",role(caller)+t+"-saved-read",p,owner));assertEquals(untouched,read("PAPI-007",role(caller)+t+"-foreign-unchanged",foreign,other));}assertEquals(5,products.count());assertEquals(2,audits.count());}
 @Test void papi012CourseConsultationInvalidStringsPreserveOrDefault()throws Exception{for(User caller:List.of(owner,admin))for(ProductType t:List.of(ProductType.COURSE,ProductType.CONSULTATION)){for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){Product p=seed(t,owner,"10",state);JsonNode before=read("PAPI-012",role(caller)+t+state+"-before",p,owner);patchBody("PAPI-012",role(caller)+t+state+"-bad-status",p,caller,Map.of("status","NOT_A_STATUS"),200);patchBody("PAPI-012",role(caller)+t+state+"-bad-price",p,caller,Map.of("price","not-numeric"),200);JsonNode after=read("PAPI-012",role(caller)+t+state+"-after",p,owner);for(String key:List.of("id","type","userId","name","description","status","price","details"))assertEquals(before.path(key),after.path(key));}Map<String,Object>b=payload(t,owner);b.put("status","NOT_A_STATUS");b.put("price","not-numeric");JsonNode n=create("PAPI-012",role(caller)+t+"-create-invalid-strings",caller,b,201);defaults(t,owner,n);assertEquals(n,read("PAPI-012",role(caller)+t+"-created-read",entity(n),owner));}}
 @Test void papi013DownloadInvalidStatusAndPricePersistedBehavior()throws Exception{for(User caller:List.of(owner,admin)){Product p=seed(ProductType.DOWNLOAD,owner,"10",ProductStatus.HIDDEN);JsonNode n=patchBody("PAPI-013",role(caller)+"-invalid-status",p,caller,Map.of("status","NOT_A_STATUS"),200);assertEquals("DRAFT",n.path("status").asText());assertEquals("10.00",n.path("price").asText());assertEquals(n,read("PAPI-013",role(caller)+"-status-persisted",p,owner));patchBody("PAPI-013",role(caller)+"-invalid-price",p,caller,Map.of("price","not-numeric"),400);assertEquals(n,read("PAPI-013",role(caller)+"-price-rejection-unchanged",p,owner));}}
 @Test void papi017UnknownAndRepeatedDeletesDoNotRemoveOtherData()throws Exception{Product control=seed(ProductType.COURSE,owner,"10",ProductStatus.DRAFT);JsonNode before=read("PAPI-017","control-before",control,owner);for(User caller:List.of(owner,admin))for(ProductType t:ProductType.values()){Product p=seed(t,owner,"10",ProductStatus.DRAFT);perform("PAPI-017",role(caller)+t+"-initial-delete",mutation(delete("/api/products/"+p.getId()),caller),204);assertTrue(products.findById(p.getId()).isEmpty());long auditCount=audits.count();for(UUID id:List.of(p.getId(),UUID.randomUUID())){perform("PAPI-017",role(caller)+t+"-missing-canonical",mutation(delete("/api/products/"+id),caller),404);perform("PAPI-017",role(caller)+t+"-missing-legacy",mutation(delete("/api/products"),caller).param("userId",owner.getUserId().toString()).param("productType",t.name()).param("id",id.toString()),404);assertEquals(1,products.count());assertEquals(auditCount,audits.count());assertEquals(before,read("PAPI-017",role(caller)+t+"-control-unchanged",control,owner));}}}
 void rejectPublication(String c,Product p,User caller,String key,String message)throws Exception{JsonNode before=read(c,role(caller)+"-before-rejected-publication",p,owner);JsonNode rejected=patchBody(c,role(caller)+"-publication-denied",p,caller,Map.of("status","PUBLISHED"),422);assertEquals(1,rejected.path("errors").size());assertEquals(message,rejected.path("errors").path(key).asText());assertEquals(before,read(c,role(caller)+"-rejected-state-unchanged",p,owner));assertEquals(p.getStatus(),products.findById(p.getId()).orElseThrow().getStatus());}
 void acceptedPublication(String c,Product p,User caller,Map<String,Object>fix)throws Exception{Map<String,Object>b=new LinkedHashMap<>(fix);b.put("status","PUBLISHED");JsonNode n=patchBody(c,role(caller)+"-corrected-publication",p,caller,b,200);assertEquals("PUBLISHED",n.path("status").asText());assertEquals(p.getId().toString(),n.path("id").asText());assertEquals(owner.getUserId().toString(),n.path("userId").asText());assertEquals(n,read(c,role(caller)+"-published-saved-read",p,owner));assertEquals(ProductStatus.PUBLISHED,products.findById(p.getId()).orElseThrow().getStatus());}
 CourseLesson article(CourseSection s){CourseLesson l=new CourseLesson();l.setSection(s);l.setTitle("QA repaired article");l.setType(LessonType.ARTICLE);l.setPosition(1);l.setContent("QA ready article");return lessons.saveAndFlush(l);}
 @Test void papi018CourseMissingSectionRepairAndPublish()throws Exception{for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){Product p=seed(ProductType.COURSE,owner,"10",state);rejectPublication("PAPI-018",p,caller,"details.sections","At least one section is required");readyArticle(p);acceptedPublication("PAPI-018",p,caller,Map.of());}}
 @Test void papi019CourseEmptySectionRepairAndPublish()throws Exception{for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){Product p=seed(ProductType.COURSE,owner,"10",state);CourseSection s=new CourseSection();s.setCourse((CourseProduct)p);s.setTitle("QA empty section");s.setPosition(1);s=sections.saveAndFlush(s);rejectPublication("PAPI-019",p,caller,"details.lessons","At least one lesson is required");article(s);acceptedPublication("PAPI-019",p,caller,Map.of());}}
 @Test void papi020CourseDownloadNegativePriceRepairAndPublish()throws Exception{for(User caller:List.of(owner,admin))for(ProductType t:List.of(ProductType.COURSE,ProductType.DOWNLOAD))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){Product p=seed(t,owner,"-1",state);if(t==ProductType.COURSE)readyArticle(p);else downloadFile(p);rejectPublication("PAPI-020",p,caller,"price","Price must be free or positive");acceptedPublication("PAPI-020",p,caller,Map.of("price","0"));}}
 @Test void papi021DownloadUnconfirmedPathRepairAndPublish()throws Exception{for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN))for(String missing:List.of("null","blank")){Product p=seed(ProductType.DOWNLOAD,owner,"10",state);FileDownloadProduct f=downloadFile(p);f.setPath(missing.equals("null")?null:"  ");files.saveAndFlush(f);rejectPublication("PAPI-021",p,caller,"details.files","At least one confirmed file is required");f.setPath("qa-metadata-only/ready.zip");files.saveAndFlush(f);acceptedPublication("PAPI-021",p,caller,Map.of());}}
 Map<String,Object> availability(boolean enabled,boolean overlap){return Map.of("day","MONDAY","enabled",enabled,"windows",overlap?List.of(Map.of("startTime","09:00","endTime","11:00"),Map.of("startTime","10:00","endTime","12:00")):List.of(Map.of("startTime","09:00","endTime","12:00")));}
 void consultationBoundary(String c,String kind,String variant,String key,String error)throws Exception{for(User caller:List.of(owner,admin))for(ProductStatus state:List.of(ProductStatus.DRAFT,ProductStatus.HIDDEN)){Map<String,Object>d=new LinkedHashMap<>();d.put("durationMinutes",30);d.put("meetingMethod","ZOOM");d.put("weeklyAvailability",List.of(availability(true,false)));Map<String,Object>b=payload(ProductType.CONSULTATION,owner);b.put("status",state.name());b.put("price","10");Map<String,Object>fix=new LinkedHashMap<>();switch(kind){case"price"->{b.put("price","0");fix.put("price","10");}case"duration"->{d.put("durationMinutes",Integer.parseInt(variant));fix.put("details",Map.of("durationMinutes",30));}case"method"->{d.put("meetingMethod",null);fix.put("details",Map.of("meetingMethod","ZOOM"));}case"location"->{d.put("meetingMethod","OTHER");d.put("customLocation","  ");fix.put("details",Map.of("customLocation","QA synthetic meeting instructions"));}case"disabled"->{d.put("weeklyAvailability",List.of(availability(false,false)));fix.put("details",Map.of("weeklyAvailability",List.of(availability(true,false))));}case"overlap"->{d.put("weeklyAvailability",List.of(availability(true,true)));fix.put("details",Map.of("weeklyAvailability",List.of(availability(true,false))));}}b.put("details",d);Product p=entity(create(c,role(caller)+state+"-otherwise-ready-draft-"+kind+variant,caller,b,201));rejectPublication(c,p,caller,key,error);acceptedPublication(c,p,caller,fix);}}
 @Test void papi022ConsultationZeroPriceRepairAndPublish()throws Exception{consultationBoundary("PAPI-022","price","zero","price","Consultations require a positive price");}
 @Test void papi023ConsultationZeroNegativeDurationRepairAndPublish()throws Exception{for(String v:List.of("0","-1"))consultationBoundary("PAPI-023","duration",v,"details.durationMinutes","Duration must be positive");}
 @Test void papi024ConsultationMissingMeetingMethodRepairAndPublish()throws Exception{consultationBoundary("PAPI-024","method","null","details.meetingMethod","Meeting method is required");}
 @Test void papi025ConsultationOtherBlankLocationRepairAndPublish()throws Exception{consultationBoundary("PAPI-025","location","blank","details.customLocation","A custom location is required for OTHER");}
 @Test void papi026ConsultationDisabledAvailabilityRepairAndPublish()throws Exception{consultationBoundary("PAPI-026","disabled","all","details.weeklyAvailability","At least one enabled valid availability range is required");}
 @Test void papi027ConsultationOverlapRepairAndPublish()throws Exception{consultationBoundary("PAPI-027","overlap","two","details.weeklyAvailability","Availability windows cannot overlap");}
}

package com.myproject.video.video_platform.controller.commerce;
import com.fasterxml.jackson.databind.*;
import com.myproject.video.video_platform.common.enums.products.*;
import com.myproject.video.video_platform.common.enums.products.course.LessonType;
import com.myproject.video.video_platform.entity.products.*;
import com.myproject.video.video_platform.entity.products.course.*;
import com.myproject.video.video_platform.entity.products.download.*;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.repository.admin.AdminAuditLogRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.junit.jupiter.api.*;
import java.util.*;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
class CatalogProductOwnershipPublicationTest extends CatalogContentBoundaryTest {
 @Autowired AdminAuditLogRepository audits;
 @AfterEach void cleanAudit(){audits.deleteAll();}
 String role(User u){return u==owner?"Creator owner":u.getRoles().iterator().next().getRoleName();}
 Map<String,Object> payload(ProductType t,User u){Map<String,Object>b=new LinkedHashMap<>();b.put("type",t.name());b.put("name","QA isolated "+t);b.put("description","QA original description");if(u!=null)b.put("userId",u.getUserId().toString());return b;}
 JsonNode create(String c,String label,User caller,Map<String,Object>b,int expected)throws Exception{return perform(c,label,mutation(post("/api/products"),caller).content(mapper.writeValueAsString(b)),expected);}
 Product entity(JsonNode n){return products.findById(UUID.fromString(n.path("id").asText())).orElseThrow();}
 JsonNode read(String c,String label,Product p,User u)throws Exception{return productRead(c,label,p,u,false);}
 JsonNode patchBody(String c,String label,Product p,User u,Map<String,Object>b,int expected)throws Exception{return perform(c,label,mutation(patch("/api/products/"+p.getId()),u).content(mapper.writeValueAsString(b)),expected);}
 void defaults(ProductType t,User expected,JsonNode n){assertEquals(t.name(),n.path("type").asText());assertEquals(expected.getUserId().toString(),n.path("userId").asText());assertEquals("DRAFT",n.path("status").asText());assertEquals("free",n.path("price").asText());assertEquals("EUR",n.path("currency").asText());assertEquals(t==ProductType.MEMBERSHIP?"RECURRING":"ONE_TIME",n.path("pricingModel").asText());if(t==ProductType.MEMBERSHIP)assertEquals("MONTH",n.path("billingInterval").asText());else assertTrue(n.path("billingInterval").isNull());Product p=entity(n);assertNotNull(p.getCreatedAt());assertEquals(expected.getUserId(),p.getUser().getUserId());assertEquals(t,p.getType());assertEquals(ProductStatus.DRAFT,p.getStatus());assertEquals(0,p.getPrice().compareTo(BigDecimal.ZERO));}
 void assertSameProduct(JsonNode expected,JsonNode actual){ObjectNodePair normalized=new ObjectNodePair(expected,actual);assertEquals(normalized.a,normalized.b,"Persisted Product semantic fields match mutation response");assertFalse(actual.path("createdAt").isNull());assertFalse(actual.path("updatedAt").isNull());}
 static class ObjectNodePair{JsonNode a,b;ObjectNodePair(JsonNode x,JsonNode y){a=x.deepCopy();b=y.deepCopy();for(JsonNode n:List.of(a,b)){var o=(com.fasterxml.jackson.databind.node.ObjectNode)n;o.remove(List.of("createdAt","updatedAt"));if(o.hasNonNull("price")&&!o.path("price").asText().equals("free"))o.put("price",new BigDecimal(o.path("price").asText()).stripTrailingZeros().toPlainString());}}}
 @Override JsonNode perform(String caseId,String label,org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder req,int expected)throws Exception{var result=mvc.perform(req).andReturn();int actual=result.getResponse().getStatus();String txt=result.getResponse().getContentAsString();JsonNode body=txt.isEmpty()?mapper.nullNode():mapper.readTree(txt);Map<String,Object> row=new LinkedHashMap<>();row.put("case_id",caseId);row.put("label",label);row.put("actual_status",actual);row.put("expected_status",expected);row.put("observed_at",java.time.Instant.now().toString());String msg=body.path("message").asText().toLowerCase();if(actual>=400){row.put("availability_unique_constraint_error",msg.contains("unique")&&msg.contains("consultation_availability_days"));row.put("availability_foreign_key_error",msg.contains("referential")&&msg.contains("availability"));}observations.add(row);assertEquals(expected,actual,caseId+" "+label+" HTTP status");return body;}
 @Test void papi001CreatorOwnsAllTypesDespiteForeignOwner()throws Exception{User other=extra("other-creator",owner);for(ProductType t:ProductType.values()){JsonNode n=create("PAPI-001",t+"-foreign-owner",owner,payload(t,other),201);defaults(t,owner,n);assertSameProduct(n,read("PAPI-001",t+"-saved-read",entity(n),owner));}assertEquals(4,products.count());assertEquals(0,audits.count());}
 @Test void papi002AdminCreatesAllTypesForSelectedCreatorAndAudits()throws Exception{User other=extra("selected-creator",owner);Set<String>created=new HashSet<>();for(ProductType t:ProductType.values()){JsonNode n=create("PAPI-002",t+"-admin-create",admin,payload(t,other),201);defaults(t,other,n);created.add(n.path("id").asText());assertSameProduct(n,read("PAPI-002",t+"-owner-read",entity(n),other));}JsonNode list=perform("PAPI-002","selected-owner-management-list",get("/api/products").param("userId",other.getUserId().toString()).cookie(auth(other)),200);Set<String>got=new HashSet<>();for(JsonNode n:list)got.add(n.path("id").asText());assertEquals(created,got);assertEquals(4,audits.count());for(var a:audits.findAll()){assertEquals(admin.getUserId(),a.getActorUserId());assertEquals("PRODUCT_CREATE",a.getAction());assertEquals("PRODUCT",a.getTargetType());assertTrue(created.contains(a.getTargetId()));assertNull(a.getBeforeSummary());assertTrue(a.getAfterSummary().contains("ownerId="+other.getUserId()));assertNotNull(a.getCreatedAt());}}
 @Test void papi003AdminInvalidOwnersNoProductsOrAudits()throws Exception{for(ProductType t:ProductType.values())for(String variant:List.of("missing","null","blank","unknown","user","admin","invalid-uuid")){Map<String,Object>b=payload(t,null);switch(variant){case"null"->b.put("userId",null);case"blank"->b.put("userId","  ");case"unknown"->b.put("userId",UUID.randomUUID().toString());case"user"->b.put("userId",buyer.getUserId().toString());case"admin"->b.put("userId",admin.getUserId().toString());case"invalid-uuid"->b.put("userId","not-a-uuid");}create("PAPI-003",t+"-"+variant,admin,b,variant.equals("unknown")?404:variant.equals("invalid-uuid")?400:403);assertEquals(0,products.count());assertEquals(0,audits.count());}}
