nt("PAY-018",p,true);}assertEquals("PAID",readOrder("PAY-018",otherId).path("status").asText());JsonNode detail=creatorOrder("PAY-018",id,"REFUNDED");assertEquals(2450,detail.path("refund").path("amountCents").asLong());assertEquals(2,detail.path("items").size());for(JsonNode item:detail.path("items"))assertEquals("revoked",item.path("access").path("state").asText());assertEquals("1",metric("PAY-018","Orders"));assertTrue(metric("PAY-018","Revenue").contains("12.25"));assertTrue(metric("PAY-018","Refunds").contains("24.50"));}
