@SpringBootTest(properties={"app.commerce.fake.auto-success=false"})
class CatalogCheckoutMatrixTest extends CommerceCheckoutIntegrationTest {
  static final Queue<Map<String,Object>> observations=new ConcurrentLinkedQueue<>();
  @Autowired MockMvc mvc;
  @Autowired ObjectMapper mapper;
  @Autowired UserRepository users;
  @Autowired ProductRepository products;
  @Autowired DownloadProductRepository downloads;
  @Autowired ConsultationProductRepository consultations;
  @Autowired CourseSectionRepository sections;
